#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "seidel-2d.h"


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;

  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++)
      A[i][j] = ((DATA_TYPE) i*(j+2) + 2) / n;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      if ((i * n + j) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
      fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j]);
    }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static void __attribute__((flatten, noinline))
kernel_seidel_2d (int tsteps,
		  int n,
		  DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  /* Local pointer with explicit restrict to help the compiler optimize
     memory accesses.  We do not use the original parameter name `A`
     after this, so the restrict contract is respected. */
  DATA_TYPE (* restrict a)[n] = A;

  /* PolyBench supplies preprocessed loop bounds (_PB_TSTEPS, _PB_N) that
     may differ from the raw parameters when running in reduced-size or
     instrumentation modes.  Cache them locally to avoid repeatedly
     expanding the macros inside the loops. */
  const int T = _PB_TSTEPS;
  const int N = _PB_N;

  /* Precompute the reciprocal once.  Modern compilers usually perform
     this transformation automatically, but making it explicit documents
     the intent and can reduce work for less aggressive compilers. */
  const DATA_TYPE one_ninth = SCALAR_VAL(1.0) / SCALAR_VAL(9.0);

  /* Simple blocking in the i-dimension.
     - Rows are still processed in strictly increasing order (1..N-2).
     - For each row, columns are processed left-to-right (1..N-2).
     This preserves the original Gauss–Seidel update order and all data
     dependencies (especially the dependence on A[i-1][j+1]).
     Only the grouping of rows is changed, which is semantically neutral
     but can help cache behavior on some architectures. */
  const int i_block = 64; /* Tunable; any value >= 1 is valid. */

  int t, ii, i, j;

#pragma scop
  for (t = 0; t < T; ++t)
  {
    /* Block the iteration space in the i dimension. */
    for (ii = 1; ii < N - 1; ii += i_block)
    {
      const int i_max = (ii + i_block < N - 1) ? (ii + i_block) : (N - 1);

      /* Process rows in the same order as the original code:
         i = 1, 2, ..., N-2. */
      for (i = ii; i < i_max; ++i)
      {
        /* Row pointers to avoid repeated 2D index arithmetic. */
        DATA_TYPE * restrict a_im1 = a[i - 1];
        DATA_TYPE * restrict a_i   = a[i];
        DATA_TYPE * restrict a_ip1 = a[i + 1];

        /* Inner loop over columns: strictly left-to-right, matching the
           original Gauss–Seidel sweep and preserving the dependence on
           A[i][j-1]. */
        for (j = 1; j < N - 1; ++j)
        {
          a_i[j] =
            ( a_im1[j-1] + a_im1[j]   + a_im1[j+1]
            + a_i  [j-1] + a_i  [j]   + a_i  [j+1]
            + a_ip1[j-1] + a_ip1[j]   + a_ip1[j+1]
            ) * one_ninth;
        }
      }
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_seidel_2d (tsteps, n, POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}

