      fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j]);
    }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_seidel_2d[[gnu::flatten, gnu::noinline]](int tsteps,
		      int n,
		      DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int t, i, j;

  /* Optimized Gauss-Seidel 2D kernel.
   *
   * Key idea:
   *   For each fixed (t, i) we traverse j from left to right. The
   *   3x3 stencil for A[i][j] and A[i][j+1] share 6 out of 9 elements.
   *   Instead of reloading all 9 neighbors from memory for every j,
   *   we keep a 3x3 "sliding window" in registers and move it by one
   *   column each iteration. This reduces memory traffic from
   *   ~9 loads per point down to ~3 loads per point after the first
   *   column.
   *
   *   Layout of the sliding window (for a fixed row i):
   *
   *      top_left   top_mid   top_right   -> row i-1
   *      mid_left   mid_mid   mid_right   -> row i
   *      bot_left   bot_mid   bot_right   -> row i+1
   *
   *   At column j, these correspond to:
   *      *_left   = row[*][j-1]
   *      *_mid    = row[*][j]
   *      *_right  = row[*][j+1]
   *
   *   After computing A[i][j], we:
   *     - Shift left/mid/right horizontally
   *     - Load only the new rightmost column (j+2) from memory
   *     - Reuse A[i][j] (the just-computed value) as the left neighbor
   *       for the next column, which preserves the Gauss-Seidel update
   *       order (new values are used immediately in the same time step).
   *
   *   Loop ordering and bounds are kept logically identical to the
   *   original code (t, then i, then j), so all data dependencies of
   *   the Gauss-Seidel scheme are preserved.
   */

#pragma scop
  const int n_  = _PB_N;
  const int ts_ = _PB_TSTEPS;

  /* Precompute j-loop limits once. Note:
   *  - Interior columns are j = 1 .. n_-2
   *  - last_j is the last interior column
   *  - main_j_end is the last column for which we both compute A[i][j]
   *    and advance the sliding window to j+1. The final interior column
   *    is handled separately without an extra window advance.
   */
  const int last_j     = n_ - 2;
  const int main_j_end = last_j - 1; /* == n_ - 3 */

  for (t = 0; t < ts_; t++)
  {
    /* Interior rows: i = 1 .. n_-2
     * When n_ < 3, this loop does not execute at all, matching
     * the original behavior (no interior points to update).
     */
    for (i = 1; i <= n_ - 2; i++)
    {
      /* Row pointers improve locality and enable the compiler to
       * generate better code (fewer address recalculations).
       * We mark them restrict to tell the compiler that these
       * three row slices do not overlap.
       */
      DATA_TYPE *restrict       row_i   = A[i];
      const DATA_TYPE *restrict row_im1 = A[i - 1];
      const DATA_TYPE *restrict row_ip1 = A[i + 1];

      /* For each row, we initialize the 3x3 window for j = 1.
       * This requires columns 0, 1, and 2 of rows i-1, i, and i+1.
       * This setup is only executed when n_ >= 3 (because i-loop
       * has no iterations otherwise), so indices 0..2 are valid.
       */

      DATA_TYPE top_left   = row_im1[0];
      DATA_TYPE top_mid    = row_im1[1];
      DATA_TYPE top_right  = row_im1[2];

      DATA_TYPE mid_left   = row_i[0];
      DATA_TYPE mid_mid    = row_i[1];
      DATA_TYPE mid_right  = row_i[2];

      DATA_TYPE bot_left   = row_ip1[0];
      DATA_TYPE bot_mid    = row_ip1[1];
      DATA_TYPE bot_right  = row_ip1[2];

      /* Main j loop:
       *
       *   - Processes columns j = 1 .. main_j_end (i.e., up to n_-3).
       *   - For each j, computes A[i][j] using the current window,
       *     then shifts the window one column to the right, loading
       *     only the new rightmost column j+2.
       *
       * The last interior column (j = last_j = n_-2) is computed
       * after this loop, using the window state resulting from the
       * final shift.
       *
       * When n_ == 3:
       *   last_j = 1, main_j_end = 0, so this loop does not execute
       *   and the single interior column j = 1 is handled by the
       *   "final column" code below, using the initial window.
       */
      for (j = 1; j <= main_j_end; j++)
      {
        /* Compute the 3x3 stencil for A[i][j] using the current window. */
        DATA_TYPE sum =
            top_left + top_mid + top_right +
            mid_left + mid_mid + mid_right +
            bot_left + bot_mid + bot_right;

        /* Use division by SCALAR_VAL(9.0) to preserve the original
         * floating-point behavior exactly (no transformation to a
         * multiplication by a precomputed reciprocal).
         */
        DATA_TYPE new_val = sum / SCALAR_VAL(9.0);

        /* Gauss-Seidel update: store the new value immediately. */
        row_i[j] = new_val;

        /* Advance the sliding window to column j+1.
         *
         * After this update, the window variables represent:
         *   *_left  = row[*][j]
         *   *_mid   = row[*][j+1]
         *   *_right = row[*][j+2]
         *
         * Note that:
         *   - new_val (A[i][j] at the current time step) becomes
         *     mid_left for the next iteration, so the dependency
         *     on A[i][j] in the computation of A[i][j+1] is preserved.
         *   - We only load three new values from memory:
         *       row_im1[j+2], row_i[j+2], row_ip1[j+2]
         *     which are the rightmost neighbors for the next column.
         */
        int jp2 = j + 2;

        top_left  = top_mid;
        top_mid   = top_right;
        top_right = row_im1[jp2];

        mid_left  = new_val;        /* use newly computed A[i][j] */
        mid_mid   = mid_right;
        mid_right = row_i[jp2];     /* still old (not yet updated) */

        bot_left  = bot_mid;
        bot_mid   = bot_right;
        bot_right = row_ip1[jp2];
      }

      /* Handle the last interior column j = last_j (i.e., n_-2).
       *
       * For n_ >= 3, we always have one interior column:
       *   - If n_ == 3, main_j_end == 0 and the loop above did not run,
       *     so the window still corresponds to j = 1 (the only interior
       *     column), and we compute it here.
       *   - If n_  > 3, the loop above ended with its window aligned
       *     to j = last_j, so we can compute A[i][last_j] directly from
       *     the current window without another shift.
       */
      if (last_j >= 1) /* true whenever the i-loop is entered */
      {
        DATA_TYPE sum =
            top_left + top_mid + top_right +
            mid_left + mid_mid + mid_right +
            bot_left + bot_mid + bot_right;

        row_i[last_j] = sum / SCALAR_VAL(9.0);
      }
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_seidel_2d (tsteps, n, POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}
