   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      if ((i * n + j) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
      fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j]);
    }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations applied:
   - Use a restrict-qualified 2D alias of A to help the compiler with
     alias analysis.
   - For each row, work with three row pointers A[i-1], A[i], A[i+1] to
     reduce index arithmetic and improve cache locality.
   - Inside the j-loop, maintain a sliding 3-column window of vertical
     sums:
         col_jm1 = A[i-1][j-1] + A[i][j-1] + A[i+1][j-1]
         col_j   = A[i-1][j]   + A[i][j]   + A[i+1][j]
         col_jp1 = A[i-1][j+1] + A[i][j+1] + A[i+1][j+1]
     so the 3x3 sum is col_jm1 + col_j + col_jp1.
     Only four scalar loads per point are needed (the three elements
     of col_jp1 and the old center), instead of nine in the naive code.
   - The Gauss–Seidel update order (row-major, left-to-right, in-place)
     is strictly preserved: at step (i,j) we read exactly the same mix
     of “old” and “already updated” values as in the original code.
*/
static void __attribute__((noinline, flatten))
kernel_seidel_2d(int tsteps,
                 int n,
                 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int t, i, j;

  /* Alias A with a restrict-qualified pointer to help the compiler
     optimize memory accesses. All subsequent accesses go through A_. */
  const int nn = n;
  DATA_TYPE (* restrict A_)[nn] = A;

  const DATA_TYPE c9 = SCALAR_VAL(9.0);

#pragma scop
  for (t = 0; t < _PB_TSTEPS; t++)
  {
    /* Sweep interior rows: 1 .. _PB_N-2 */
    for (i = 1; i < _PB_N - 1; i++)
    {
      /* Row pointers for the three rows touched by the 3x3 stencil. */
      DATA_TYPE * restrict Arowm1 = A_[i-1];
      DATA_TYPE * restrict Arow   = A_[i];
      DATA_TYPE * restrict Arowp1 = A_[i+1];

      /* Initialize vertical 3-point sums for columns 0 and 1.
         col_jm1 corresponds to column j-1, col_j to column j. */
      DATA_TYPE col_jm1 = Arowm1[0] + Arow[0] + Arowp1[0];
      DATA_TYPE col_j   = Arowm1[1] + Arow[1] + Arowp1[1];

      /* Sweep interior columns: 1 .. _PB_N-2 */
      for (j = 1; j < _PB_N - 1; j++)
      {
        /* Vertical sum for column j+1.
           Values in this column have not yet been updated in the current
           time step, matching the original Gauss–Seidel ordering. */
        DATA_TYPE col_jp1 = Arowm1[j+1] + Arow[j+1] + Arowp1[j+1];

        /* Save the old center value so we can update column sums
           after overwriting A[i][j]. */
        DATA_TYPE center_old = Arow[j];

        /* Sum of the full 3x3 neighborhood via the three column sums. */
        DATA_TYPE sum = col_jm1 + col_j + col_jp1;

        /* Gauss–Seidel update: identical arithmetic to the original
           kernel (sum divided by 9.0). */
        DATA_TYPE center_new = sum / c9;
        Arow[j] = center_new;

        /* Update the current-column vertical sum so that A[i][j] is
           seen as updated when it becomes a left neighbor in the
           next iteration (j+1). */
        col_j += center_new - center_old;

        /* Slide the 3-column window one step to the right. */
        col_jm1 = col_j;
        col_j   = col_jp1;
      }
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_seidel_2d (tsteps, n, POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}
