static
void kernel_seidel_2d[[gnu::flatten, gnu::noinline]](int tsteps,
		      int n,
		      DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  /* Create a local restrict-qualified alias to help the compiler with
     alias analysis.  The POLYBENCH_2D macro typically exposes A as a
     VLA; in function parameters this is a pointer-to-VLA, which we
     rebind to a restrict-qualified pointer.  No other aliases are used
     to access this storage inside the kernel. */
  DATA_TYPE (* __restrict A_)[n] = A;

  /* Precompute 1/9 as a scalar of the appropriate precision to avoid a
     division in the inner loop.  Compilers usually do this, but being
     explicit makes the intent clear. */
  const DATA_TYPE inv9 = SCALAR_VAL(1.0) / SCALAR_VAL(9.0);

#pragma scop
  for (int t = 0; t <= _PB_TSTEPS - 1; ++t)
    for (int i = 1; i <= _PB_N - 2; ++i)
    {
      /* Row pointers for better locality and fewer address calculations. */
      DATA_TYPE * __restrict Aim1 = A_[i - 1]; /* row i-1 */
      DATA_TYPE * __restrict Ai   = A_[i];     /* row i   */
      DATA_TYPE * __restrict Aip1 = A_[i + 1]; /* row i+1 */

      const int j_start = 1;
      const int j_end   = _PB_N - 2;

      /* For very small problem sizes with no interior points, this matches
         the original loop semantics (the j-loop would not execute). */
      if (j_end < j_start)
        continue;

      /* --- Optimized 1D sliding window along j -------------------------
       *
       * We compute the 9-point Gauss–Seidel stencil using a 3×3 window
       * that slides along the row:
       *
       *    [p_im1 p_i p_ip1]   = A[i-1][j-1..j+1]
       *    [c_im1 c_i c_ip1]   = A[i  ][j-1..j+1]
       *    [n_im1 n_i n_ip1]   = A[i+1][j-1..j+1]
       *
       * For each step in j, we:
       *   - reuse 6 of the 9 values from the previous position, and
       *   - load only the 3 new "right column" values from memory.
       *
       * This reduces memory loads per grid point from ~9 to ~3 while
       * preserving Gauss–Seidel update semantics:
       *
       *   * Ai[j-1]    is always the UPDATED value from the current row.
       *   * Ai[j],Ai[j+1] remain OLD values when computing Ai[j].
       *   * Aim1[*],Aip1[*] are never updated within this loop.
       */

      /* Preload data for j = 1: indices {0,1,2} in each of the three rows.
         These are exactly the elements used by the original kernel at j=1. */
      DATA_TYPE p_im1 = Aim1[0]; /* A[i-1][0] = A[i-1][j-1] */
      DATA_TYPE p_i   = Aim1[1]; /* A[i-1][1] = A[i-1][j]   */
      DATA_TYPE p_ip1 = Aim1[2]; /* A[i-1][2] = A[i-1][j+1] */

      DATA_TYPE c_im1 = Ai[0];   /* A[i][0]   = A[i][j-1] (boundary, unchanged) */
      DATA_TYPE c_i   = Ai[1];   /* A[i][1]   = A[i][j]   (old value)           */
      DATA_TYPE c_ip1 = Ai[2];   /* A[i][2]   = A[i][j+1] (old value)           */

      DATA_TYPE n_im1 = Aip1[0]; /* A[i+1][0] = A[i+1][j-1] */
      DATA_TYPE n_i   = Aip1[1]; /* A[i+1][1] = A[i+1][j]   */
      DATA_TYPE n_ip1 = Aip1[2]; /* A[i+1][2] = A[i+1][j+1] */

      int j = j_start;

      /* Main part of the row: j = 1 .. j_end-1.
       * Each iteration computes A[i][j] with the current window and then
       * slides the window one column to the right. */
      for (; j < j_end; ++j)
      {
        DATA_TYPE new_val =
          (p_im1 + p_i + p_ip1 +
           c_im1 + c_i + c_ip1 +
           n_im1 + n_i + n_ip1) * inv9;

        Ai[j] = new_val;

        /* Slide window to j+1.
         *
         * Row i-1 and row i+1: shift left, then load the new right element.
         * Row i (current):     the just-computed new_val becomes the left
         *                      neighbor for the next column; the previous
         *                      right neighbor becomes the new center; and we
         *                      load the new right neighbor from memory,
         *                      which still holds the old value at j+2.
         */
        p_im1 = p_i;
        p_i   = p_ip1;
        p_ip1 = Aim1[j + 2];

        c_im1 = new_val;  /* updated A[i][j] becomes left neighbor */
        c_i   = c_ip1;    /* old A[i][j+1] becomes center */
        c_ip1 = Ai[j + 2];/* old A[i][j+2] becomes right */

        n_im1 = n_i;
        n_i   = n_ip1;
        n_ip1 = Aip1[j + 2];
      }

      /* Final point in the row: j = j_end.
       * After the loop above, the sliding window is already aligned with
       * column j_end, so we can compute the last update without further
       * memory loads or shifts. */
      {
        DATA_TYPE new_val =
          (p_im1 + p_i + p_ip1 +
           c_im1 + c_i + c_ip1 +
           n_im1 + n_i + n_ip1) * inv9;

        Ai[j_end] = new_val;
      }
    }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);


